                    ptsString = " point";
                }
                if (showPoints && !storyViewHolder.story.isComment) {
                    storyViewHolder.metaView.setText(storyViewHolder.story.score + ptsString + " • " + url + " • " + storyViewHolder.story.getTimeFormatted());
