            int startTime = currentTime;
            if (currentType == 1) {
                startTime = currentTime - 60*60*24;
            } else if (currentType == 2) {
                startTime = currentTime - 60*60*48;
            } else if (currentType == 3) {
                startTime = currentTime - 60*60*24*7;
            }

            loadTopStoriesSince(startTime);

