        });

        updateBottomSheetMargin(Utils.getNavigationBarHeight(getResources()));

        webViewContainer.setPadding(0, Utils.shouldUseTransparentStatusBar(getContext()) ? Utils.getStatusBarHeight(getResources()) : 0, 0, 0);

