    public StoryRecyclerViewAdapter(List<Story> items,
                                    boolean shouldShowPoints,
                                    boolean shouldUseCompactView,
                                    boolean shouldShowThumbnails,
                                    boolean shouldShowIndex,
                                    boolean shouldHideJobs,
