                                    String submissionsUserName) {
        stories = items;
        showPoints = shouldShowPoints;
        compactView = shouldUseCompactView;
        thumbnails = shouldShowThumbnails;
        showIndex = shouldShowIndex;
        hideJobs = shouldHideJobs;
