            view.findViewById(R.id.comments_empty).setVisibility(View.VISIBLE);
            bottomSheet.setVisibility(View.GONE);
            webViewContainer.setVisibility(View.GONE);

            swipeRefreshLayout.setEnabled(false);
            return;
