                    finish();
                    overridePendingTransition(0, 0);
                }
            }
        });

        swipeRefreshLayout = findViewById(R.id.submissions_swiperefreshlayout);
        swipeRefreshLayout.setBackgroundResource(ThemeUtils.getBackgroundColorResource(this));

