    private void setupAdapter() {
        adapter = new StoryRecyclerViewAdapter(stories,
                Utils.shouldShowPoints(getContext()),
                Utils.shouldUseCompactView(getContext()),
                Utils.shouldShowThumbnails(getContext()),
