            if (config.getSASs().isEmpty())
                return null;

            if (SASs == null) {
                StringBuilder buf = new StringBuilder();
                try (ZipFile zip = new ZipFile(data)) {
                    for (String sas : config.getSASs()) {
                        ZipEntry entry = zip.getEntry(sas);
                        if (entry == null)
