                rename.getArgs().set(Arrays.asList("--in-jar", "{input}", "--out-jar", "{output}", "--srg-in", "{mappings}"));
                rename.setHasLog(false);
                rename.getInput().set(merged);
                rename.getOutput().set(srged);
                rename.getMappings().set(obf2Srg);
                rename.apply();
                return srged;
            } else {
                return merged;
            }
        }
    }

