            logger.log("Issuing boot commands...");
            defaultConfig.getBootCommands_commands().forEach(command -> {
                logger.log(">>> "+command);
                api.getVirtualProcessor().dispatchCommand(command);
            });
        }

        WhitelistConfig.empty();
        DefaultConfig.empty();
        ScalarFamilyConfig.empty();

        this.isRunning = true;
        return true;
    }
