    @Transactional(rollbackFor = Exception.class)
    public ResultTO<Integer> deleteScene(int sceneId) {
        try {
            publicSceneMapper.deleteScene(sceneId);
            return ResultTO.OK();
        } catch (Exception e) {
            logger.error(e.getMessage());
            return ResultTO.FAILURE(e.getMessage());
        }
    }

