    private void addExercise(List<TExerciseInfo> tExerciseInfo, List<TExerciseInfoVO> exerciseInfos, UserInfo loginUser, int exerciseId) {
        if (exerciseInfos == null || exerciseInfos.isEmpty()) {
            return;
