            TExerciseInfo info = (TExerciseInfo) new TExerciseInfo()
                    .setExerciseId(exerciseId)
                    .setContent(vo.getContent())
                    .setPrefix(vo.getPrefix())
                    .setCreateTime(new Date())
                    .setCreateUser(loginUser.getUserId());
            tExerciseInfo.add(info);
        }
    }

