        if (!homeworkDistributionStudentList.isEmpty()) {
            homeworkDistributionStudentService.removeByIds(
                    homeworkDistributionStudentList.stream()
                            .map(THomeworkDistributionStudent::getId)
                            .collect(Collectors.toList()));
        }
    }

