        //同级目录信息
        List<CourseCatalogue> courseCatalogues = this.list(new QueryWrapper<CourseCatalogue>()
                .eq("parent_id", courseCatalogue.getParentId())
                .eq("delete_flag", 0));
        BusinessResponseEnum.FAILMOVE.assertIsNotEmpty(courseCatalogues);
