                .setViewTime(param.getViewTime())
                .setIgnoreCase(param.getIgnoreCase())
                .setUnselectedGiven(param.getUnselectedGiven())
                .setUpdateTime(new Date())
                .setUpdateUser(loginUser.getUserId());
        //更新
