            List<TStuHomework> stuHomeworkList = stuHomeworks.stream()
                    .filter(item -> item.getEndTime() != null)
                    .map(stuHomework -> {
                        stuHomework.setEndTime(null)
                                .setUpdateTime(new Date())
                                .setUpdateUser(loginUser.getUserId());
