                    }).collect(Collectors.toList());
            if (!stuHomeworkList.isEmpty()) {
                BusinessResponseEnum.SAVEORUPDATEFAIL.assertIsTrue(stuHomeworkService.saveOrUpdateBatch(stuHomeworkList));
            }
        }
