        columnInfos.forEach(columnInfo -> {
            String comment = columnInfo.getComment();
            if (!StrUtil.isBlank(comment)) {
                content.append("    /**\n")
                    .append("     * ").append(comment.trim()).append("\n")
                    .append("     */\n");
