        sql.append(wrap(getRealTable(tableName)));
        sql.append(BLANK).append(BRACKET_LEFT)
            .append(fields)
            .append(BRACKET_RIGHT).append(BLANK);
        sql.append(VALUES).append(questions);
        return sql.toString();
    }


