    public List<Column> getSortedColumns() {
        ArrayList<Column> arrayList = new ArrayList<>(columns);
        // 生成字段排序
        arrayList.sort(Comparator.comparingInt((Column c) -> c.getProperty().length())
            .thenComparing(Column::getProperty));
        return arrayList;
