        {
            chunk3.populate(chunkGenrator);
        }

        if (chunk != null && chunk1 != null && chunkProvider.getLoadedChunk(this.x + 1, this.z - 1) != null)
        {
            chunk.populate(chunkGenrator);
        }

        if (chunk != null && chunk3 != null)
        {
