                String s2 = ((String) s1).substring(s.length());
                props.getProperty((String) s1);
                Set<String> set = new HashSet<String>();
                ShaderProfile shaderprofile = parseProfile(s2, props, set, shaderOptions);

                if (shaderprofile != null)
                {
