            }
            else
            {
                Properties properties = new PropertiesOrdered();
                properties.load(inputstream);
                inputstream.close();
                String s = properties.getProperty(key);

                if (s == null)
                {
                    return valDef;
                }
                else
                {
                    List<String> list = Arrays.asList(validValues);

                    if (!list.contains(s))
