                    while (true)
                    {
                        String s = bufferedreader.readLine();

                        if (s == null)
                        {
                            bufferedreader.close();
                            break;
                        }

                        s = applyOptions(s, ashaderoption);
                        stringbuilder.append(s).append('\n');

                        if (macrostate.processLine(s))
                        {
                            ShaderLine shaderline = ShaderParser.parseLine(s);

                            if (shaderline != null)
                            {
