                                                    }
                                                    else if (shaderline.isConstBoolSuffix("MipmapEnabled", true))
                                                    {
                                                        if (ShaderParser.isComposite(filename) || ShaderParser.isDeferred(filename) || ShaderParser.isFinal(filename))
