        }
        else
        {
            int j = str.charAt(i) - 48;

            if (p == ProgramShadow)
            {
                if (j >= 0 && j <= 1)
                {
                    drawBuffer = j + 36064;
                    usedShadowColorBuffers = Math.max(usedShadowColorBuffers, j);
                }

