    private void updateMirrorButton()
    {
        Mirror mirror = this.tileStructure.getMirror();

        switch (mirror)
        {
            case NONE:
                this.mirrorButton.displayString = "|";
                break;

            case LEFT_RIGHT:
                this.mirrorButton.displayString = "< >";
                break;

            case FRONT_BACK:
                this.mirrorButton.displayString = "^ v";
        }
    }

    private void updateDirectionButtons()
