            Assert.assertTrue(resInOneIDC.containsAll(mqInThisIDC));
        }

        Assert.assertTrue(hasAllocateAllQ(cidAll,mqAll,resAll));
        if (print) {
            System.out.println("-------------------------------------------------------------------");
        }
    }


