		Image base;
		private Image icon;

		public Tool(Asset asset) {
			super();

			hotArea.blockLevel = PointerArea.ALWAYS_BLOCK;
			base = new Image(Asset.getAssetFilePath(asset));
			SmartTexture texture = new SmartTexture(getBitmap(Asset.getAssetFilePath(asset)));
			format(texture.width, texture.height);
			add( base );
		}

		public void format(int width, int height) {
			this.width = width;
			this.height = height;
		}

		public void icon(Asset asset) {
			if (icon == null) icon = new Image(Asset.getAssetFilePath(asset));
			add(icon);
		}

		@Override
		protected void createChildren() {
			super.createChildren();


		}

		@Override
		protected void layout() {
			super.layout();

			base.x = x;
			base.y = y;

			if (icon != null){
				icon.x = x + (width()- icon.width())/2f;
				icon.y = y + (height()- icon.height())/2f;
			}
		}

		public void alpha( float value ){
			base.alpha(value);
			if (icon != null) icon.alpha(value);
		}

		@Override
		protected void onPointerDown() {
			base.brightness( 1.4f );
		}

		@Override
		protected void onPointerUp() {
			if (active) {
				base.resetColor();
			} else {
				base.tint( BGCOLOR, 0.7f );
			}
		}

		public void enable( boolean value ) {
			if (value != active) {
				if (icon != null) icon.alpha( value ? 1f : 0.4f);
				active = value;
			}
		}
	}

