			blob.fullyClear();
		}
		addVisuals(); //this also resets existing visuals
		traps.clear();

		for (CustomTilemap t : customTiles){
			if (t instanceof FadingTraps){
				((FadingTraps) t).remove();
			}
		}

		GameScene.resetMap();
		Dungeon.observe();
	}

