			}

			if (blocking == null){
				blocking = Dungeon.level.losBlocking;
			}

			int viewDist = c.viewDistance;
			if (c instanceof Hero){
				viewDist *= 1f + 0.25f*((Hero) c).pointsInTalent(Talent.FARSIGHT);
