			int counter = 0;

			do {
				counter++;
				tagName = keyWord + counter;
			} while (contentTagNames.contains(tagName) || reservedNames.contains(tagName));

			tag.setName(tagName);

			// add the tag to the map of tags
			Map<String, ContentTag> tags = getContentTags();

			tags.put(tagName, tag);

			// return the tag
			return tag;
		}

