			loadTemplateTagIds();

			List<TemplateTag> tags = t.getObjects(TemplateTag.class, tagIds, getObjectInfo().isEditable());

			for (TemplateTag tag : tags) {
				templateTags.put(tag.getName(), tag);
			}

			return templateTags;
