				t.addTransactional(new RemovePermsTransactional(Node.TYPE_NODE, ObjectTransformer.getInt(folderId, 0)));
				t.addTransactional(new RemovePermsTransactional(Node.TYPE_CHANNEL, ObjectTransformer.getInt(folderId, 0)));
