			if (channelSet == null) {
				if (isEmptyId(channelSetId)) {
					channelSet = new HashMap<Integer, Integer>();
				} else {
					channelSet = DBUtils.select("SELECT id, channel_id FROM template WHERE channelset_id = ?", ps -> {
