				stmt.setObject(1, object.getTType());
				stmt.setObject(2, object.getId());
				stmt.setInt(3, nodeId);
			}

			@Override
			public void handleResultSet(ResultSet rs) throws SQLException, NodeException {
				while (rs.next()) {
					result.add(rs.getInt("c"));
				}
			}
		});

