	private List<String> getColumns(String table) throws NodeException {
		try {
			return Collections.unmodifiableList(DB.getTableColumns(handle, table));
		} catch (SQLException e) {
			throw new NodeException("Error while getting columns of table {" + table + "}", e);
		}
