	 * table must have a unique column "id". required for all versioning
	 * operations.
	 * @param table name of databasetable. example: price
	 * @throws NodeException
	 */
	public void setTable(String table) throws NodeException {
		this.table = table;
		tableColumns = getVersionedColumns(table);
		nonVersionedColumns = getNonVersionedColumns(table);
		columnsList = "";
		questionMarkList = "";
		boolean first = true;

		for (Iterator<String> i = tableColumns.iterator(); i.hasNext();) {
			if (first) {
				first = false;
			} else {
				columnsList += ",";
				questionMarkList += ",";
			}
			columnsList += i.next();
			questionMarkList += "?";
		}

		insertSQLStatement = "INSERT INTO " + table + "_nodeversion (" + columnsList
				+ ", nodeversiontimestamp, nodeversion_user, nodeversionlatest, nodeversionremoved, nodeversion_autoupdate) VALUES ("
				+ StringUtils.repeat("?", tableColumns.size() + 5, ",") + ")";

		insertSQLStatementNoAutoupdate = "INSERT INTO " + table + "_nodeversion (" + columnsList
				+ ", nodeversiontimestamp, nodeversion_user, nodeversionlatest, nodeversionremoved) VALUES ("
				+ StringUtils.repeat("?", tableColumns.size() + 4, ",") + ")";
	}

