	 * (non-Javadoc)
	 * @see com.gentics.lib.datasource.WriteableDatasource#store(com.gentics.lib.datasource.DatasourceRecordSet)
	 */
	public DatasourceInfo store(DatasourceRecordSet rst) throws DatasourceException {
