		PreparedStatement st = null;
		ResultSet res = null;

		try {
			st = t.prepareStatement("SELECT * from logcmd WHERE id = ?");
			st.setInt(1, id);

			res = st.executeQuery();
			if (res.next()) {
				return new Log(res);
			} else {
				return null;
			}
		} catch (SQLException e) {
			throw new NodeException("Error while getting logged cmd", e);
		} finally {
			t.closeResultSet(res);
			t.closeStatement(st);
		}
	}

