	 */
	public final static Function<Permissions, FilePrivileges> TRANSFORM2FILE = perms -> {
		FilePrivileges filePerms = new FilePrivileges();
		for (Privilege priv : Privilege.forRoleCheckType(File.TYPE_FILE)) {
